function applyPreferences(){var lang=state.language||'en',theme=state.theme||'light',root=document.documentElement;root.lang=lang;root.dir=lang==='ar'?'rtl':'ltr';root.dataset.theme=theme;var map=i18n[lang]||{};var walker=document.createTreeWalker(document.getElementById('app'),NodeFilter.SHOW_TEXT);while(walker.nextNode()){var n=walker.currentNode,key=n.nodeValue.trim();if(map[key])n.nodeValue=n.nodeValue.replace(key,map[key])}document.querySelectorAll('[title],[aria-label]').forEach(function(el){['title','aria-label'].forEach(function(a){var v=el.getAttribute(a);if(v&&map[v])el.setAttribute(a,map[v])})});var q=document.getElementById('global-search');if(q)q.placeholder=map['Search the Vault']||'Search the Vault…'}
function save(){localStorage.setItem('cervel-workspace-v3',JSON.stringify({notes:notes,state:state}))}function restore(){try{var x=JSON.parse(localStorage.getItem('cervel-workspace-v3'));if(x&&Array.isArray(x.notes)){notes=x.notes;state=Object.assign(state,x.state||{})}}catch(e){localStorage.removeItem('cervel-workspace-v3')}state.askLoading=false;state.askError=''}function clientId(){var key='cervel-demo-client-id',id=localStorage.getItem(key);if(!id){id='browser-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));localStorage.setItem(key,id)}return id}function note(){return notes.find(function(n){return n.id===state.selected})||notes[0]}function event(t,d){state.events.push([t,d]);save();if(t==='GRAPH_NODE_FOCUSED')setTimeout(function(){openGraphTarget(d)},120)}function toast(m){var x=document.createElement('div');x.className='toast';x.textContent=m;document.body.appendChild(x);setTimeout(function(){x.remove()},2200)}
function title(){return '<header class="titlebar"><div class="traffic"><i></i><i></i><i></i></div><span class="brand">CERVEL</span><div class="search"><input id="global-search" aria-label="Search the Vault" placeholder="Search the Vault…" value="'+esc(state.query)+'"><kbd>⌘ K</kbd></div><span class="pill"><span class="dot"></span>Local Node healthy</span><span class="pill">Synthetic demo</span><div class="locale-controls"><select class="language-select" id="language-select" aria-label="Language">'+languages.map(function(l){return '<option value="'+l[0]+'" '+(state.language===l[0]?'selected':'')+'>'+l[1]+'</option>'}).join('')+'</select><button class="theme-toggle" data-theme-toggle aria-label="'+(state.theme==='dark'?'Use day mode':'Use night mode')+'">'+(state.theme==='dark'?'☀︎':'☾')+'</button></div></header>'}
function rail(){return '<aside class="rail">'+views.map(function(v){return '<button class="'+(state.view===v[0]?'active':'')+'" data-view="'+v[0]+'" title="'+v[2]+'" aria-label="'+v[2]+'">'+v[1]+'</button>'}).join('')+'<button class="bottom" data-action="reset" title="Reset demo">↻</button></aside>'}
function classifyContent(title,body,corpus){var text=(title+' '+body).toLowerCase(),rules=corpus==='life'?[['Health','Care',['health','medical','doctor','wellbeing']],['Finance','Budget',['finance','budget','revenue','cost','pricing']],['Travel','Plans',['travel','trip','flight','hotel']],['Relationships & Family','Family',['family','partner','relationship']],['Work & Career','Career Plans',['career','work','job','professional']],['Education','Learning',['education','learn','course','research']],['Projects','Active',['project','roadmap','milestone','alpha']],['Personal Knowledge','Research',['knowledge','research','source','note']],['Digital Life','Software',['software','github','web','digital']]]:[['Strategy','Plans',['strategy','vision','mission','objective']],['Finance','Forecasts',['finance','budget','revenue','cost','pricing']],['Products','Roadmaps',['product','feature','roadmap','release']],['Customers','Needs',['customer','client','account']],['Sales','Pipeline',['sales','pipeline','deal','proposal']],['Research','Evidence',['research','study','evidence','source']],['Technology','Architecture',['technology','architecture','software','infrastructure']],['Data','Governance',['data','schema','analytics']],['AI / Agents','Agents',['ai','agent','model','prompt']],['Projects','Active',['project','milestone','deliverable']]];for(var i=0;i<rules.length;i++)if(rules[i][2].some(function(term){return text.includes(term)}))return{mega:rules[i][0],sub:rules[i][1],confidence:.91};return corpus==='life'?{mega:'Personal Knowledge',sub:'Notes',confidence:.72}:{mega:'Institutional Knowledge',sub:'Methods',confidence:.72}}
function membershipFor(n,corpus){var key=corpus+':'+n.id;if(state.memberships&&state.memberships[key])return state.memberships[key];return classifyContent(n.title,n.body,corpus)}
function fileKnowledge(n,corpus){var result=classifyContent(n.title,n.body,corpus),key=corpus+':'+n.id;state.memberships=state.memberships||{};state.memberships[key]=result;state.collapsed[result.mega]=false;state.subcollapsed[result.mega+' / '+result.sub]=false;state.filingReceipt=(corpus==='life'?'Life':'Enterprise')+' › '+result.mega+' › '+result.sub+' · '+Math.round(result.confidence*100)+'% confidence';event('KNOWLEDGE_AUTO_FILED',state.filingReceipt);return result}
function explorer(){var taxonomy=state.corpus==='life'?lifeTaxonomy:enterpriseTaxonomy,vault=state.corpus==='life'?'Atlas Life Vault':'CERVEL Inc. Knowledge Vault';return '<aside class="explorer"><div class="pane-head">VAULT EXPLORER <button data-action="new-note" aria-label="Add knowledge">＋</button></div><div class="corpus-switch explorer-switch" aria-label="Corpus switcher"><button data-corpus="life" class="'+(state.corpus==='life'?'active':'')+'"><i class="corpus-dot life"></i>Life</button><button data-corpus="enterprise" class="'+(state.corpus==='enterprise'?'active':'')+'"><i class="corpus-dot enterprise"></i>Enterprise</button></div><div class="vault"><b><i class="corpus-dot '+state.corpus+'"></i>'+vault+'</b><small>'+(state.corpus==='life'?'Encrypted · private by default':'Tenant isolated · CERVEL Inc.')+'</small></div><div class="taxonomy-heading">MEGA TABS · SEMANTIC VIEWS</div>'+taxonomy.map(function(branch){var mega=branch[0],subs=branch[1],megaItems=notes.filter(function(n){return membershipFor(n,state.corpus).mega===mega}),closed=state.collapsed[mega]!==false;return '<div class="folder-row"><button class="collapse '+(closed?'closed':'')+'" data-collapse="'+esc(mega)+'" aria-label="'+(closed?'Expand ':'Collapse ')+esc(mega)+'">⌄</button><button class="folder" data-semantic="'+esc(mega)+'|">'+esc(mega)+' <span class="folder-count">'+megaItems.length+'</span></button></div>'+(closed?'':subs.map(function(sub){var path=mega+' / '+sub,subItems=megaItems.filter(function(n){return membershipFor(n,state.corpus).sub===sub}),subClosed=state.subcollapsed[path]!==false;return '<div class="subtab-row"><button class="collapse '+(subClosed?'closed':'')+'" data-subcollapse="'+esc(path)+'" aria-label="'+(subClosed?'Expand ':'Collapse ')+esc(sub)+'">⌄</button><button class="subtab" data-semantic="'+esc(mega)+'|'+esc(sub)+'">'+esc(sub)+' <span class="folder-count">'+subItems.length+'</span></button></div>'+(subClosed?'':subItems.map(function(n){return '<button class="file corpus-file '+(n.id===state.selected&&state.view==='notes'?'active':'')+'" data-note="'+esc(n.id)+'"><b>◇</b><span>'+esc(n.title)+'</span></button>'}).join(''))}).join(''))}).join('')+'</aside>'}
function scopebar(){return state.corpus==='life'?'<div class="scopebar"><span>⌂ Atlas Life Vault</span><span>›</span><select id="privacy-select" aria-label="Life privacy"><option value="private" '+(state.privacy==='private'?'selected':'')+'>Private</option><option value="sealed" '+(state.privacy==='sealed'?'selected':'')+'>Sealed</option></select><span class="authority"><span class="privacy-badge '+(state.privacy==='sealed'?'sealed':'')+'">'+(state.privacy==='sealed'?'Sealed · unlock required':'Private · local only')+'</span></span></div>':'<div class="scopebar"><select id="tenant-select" aria-label="Enterprise tenant"><option value="cervel-inc">CERVEL Inc.</option></select><span>›</span><select id="scope-select" aria-label="Enterprise scope"><option value="organization">Organization</option><option value="semantic-platform" '+(state.scope==='semantic-platform'?'selected':'')+'>Product · Semantic Platform</option><option value="investor-demo" '+(state.scope==='investor-demo'?'selected':'')+'>Project · Investor Demo</option></select><span class="authority"><span class="authority-badge">Authority · role gated</span></span></div>'}
function tabs(){var v=views.find(function(x){return x[0]===state.view});var label=state.view==='notes'?note().title:state.view==='folder'?state.folder:(v?v[2]:'Workspace');return '<div class="tabs"><button class="tab">◇ '+esc(label)+' &nbsp; ×</button></div>'}
function home(){var life=state.corpus==='life';return '<section class="view hero"><small style="color:var(--accent);font-weight:750;letter-spacing:.1em">'+(life?'LIFE CORPUS · USER-OWNED':'ENTERPRISE CORPUS · TENANT-AWARE')+'</small><h1>'+(life?'Your life, remembered<br>on your terms.':'Organizational knowledge,<br>with authority.')+'</h1><p>'+(life?'Private memories, projects, health, learning, and goals become useful semantic views while remaining encrypted and locally owned.':'Strategy, operations, customers, data, and institutional memory converge inside explicit tenant and authority boundaries.')+'</p><div class="demo-ribbon"><span>5-minute investor path</span><b>Vault → cited answer → archive → Trace → graph → deliverable</b><button class="secondary" data-action="investor-tour">'+(state.tourComplete?'Replay demo':'Start demo')+'</button></div>'+(state.tourComplete?'<div class="tour-complete">✓ Investor path completed · the synthetic Vault can be reset and replayed at any time.</div>':'')+'<div class="proof-grid"><div class="proof"><b>Local-first ownership</b><small>Vault remains user controlled</small></div><div class="proof"><b>100% provenance</b><small>Claims trace to evidence</small></div><div class="proof"><b>Model independent</b><small>Reasoning engines are replaceable</small></div><div class="proof"><b>Zero duplication</b><small>Semantic views share CKOs</small></div></div><div class="corpus-summary"><div class="metric"><strong>'+(life?'17':'18')+'</strong><span>semantic branches</span></div><div class="metric"><strong>16</strong><span>canonical CKOs</span></div><div class="metric"><strong>0</strong><span>duplicated files</span></div></div><div class="semantic-demo"><b>One object, multiple meanings</b><p class="sub">“CERVEL Alpha project summary” is stored once, then projected into the views that need it.</p><div class="semantic-path"><span>◇ Canonical CKO</span><b>→</b><span class="privacy-badge">Life · Projects</span><span class="authority-badge">Enterprise · Projects · Approved target</span></div></div><div class="grid"><button class="card" data-view="notes"><i>▤</i><b>Explore '+(life?'Life':'Enterprise')+' knowledge</b><small>Open canonical objects through semantic views</small></button><button class="card" data-view="graph"><i>◉</i><b>Cross-corpus graph</b><small>See shared objects without duplication</small></button><button class="card" data-view="trace"><i>↗</i><b>Authority & provenance</b><small>Inspect evidence, policy, and receipts</small></button><button class="card" data-view="ask"><i>✦</i><b>Ask with citations</b><small>Reason within the active corpus scope</small></button></div></section>'}
function notesView(){var n=note(),life=state.corpus==='life';return '<section class="view"><input class="note-title" id="note-title" value="'+esc(n.title)+'" aria-label="Note title"><div class="meta"><span class="corpus-badge">Canonical CKO · '+esc(n.id)+'</span><span class="'+(life?'privacy-badge':'authority-badge')+'">'+(life?(state.privacy==='sealed'?'Sealed':'Private'):'Inferred · target Approved')+'</span><span>◇ '+esc(n.folder)+'</span>'+n.tags.map(function(t){return '<span class="tag">#'+esc(t)+'</span>'}).join('')+'</div><div class="provenance-panel"><b>Provenance preserved</b><br><small>'+esc(n.source)+' · semantic membership only · content stored once</small></div>'+(n.url?'<a class="source-link" href="'+esc(n.url)+'" target="_blank" rel="noopener noreferrer">↗ Open original source</a>':'')+'<textarea class="editor" id="note-body" aria-label="Note body">'+esc(n.body)+'</textarea></section>'}
function folderView(){var parts=state.folder.split(' / '),mega=parts[0],sub=parts[1]||'',items=notes.filter(function(n){var m=membershipFor(n,state.corpus);return m.mega===mega&&(!sub||m.sub===sub)});return '<section class="view"><div class="folder-hero"><div class="folder-icon">◇</div><div><h1>'+esc(state.folder)+'</h1><p class="sub">'+items.length+' canonical knowledge objects in this semantic view</p></div></div><div class="notice">This is a semantic view. Objects remain stored once and may appear in multiple corpus branches.</div><div class="results">'+(items.length?items.map(function(n){return '<button class="result" data-note="'+esc(n.id)+'"><b>'+esc(n.title)+'</b><p>'+esc(n.body.replace(/^# .*\n+/, '').slice(0,180))+'…</p><small>'+esc(n.source)+' · '+esc(membershipFor(n,state.corpus).mega)+' › '+esc(membershipFor(n,state.corpus).sub)+'</small></button>'}).join(''):'<div class="notice">This subtab is ready for automatically or manually added knowledge.</div>')+'</div></section>'}
function integrationsView(){var groups=[['FILES & KNOWLEDGE',[['△','Google Drive','Documents, Sheets, Slides and shared drives'],['◇','Dropbox','Files, folders and team spaces'],['▧','Microsoft OneDrive','Microsoft 365 files and SharePoint'],['N','Notion','Pages, databases and team knowledge'],['◫','Box','Enterprise content and governed files'],['⌁','Web Sources','Webpages, RSS feeds and public research']]],['COMMUNICATION',[['#','Slack','Channels, threads and shared files'],['T','Microsoft Teams','Chats, meetings and channel knowledge'],['✉','Gmail','Permission-scoped email and attachments'],['◉','Google Calendar','Events, decisions and meeting context']]],['BUSINESS SYSTEMS',[['◎','Salesforce','CRM accounts, opportunities and activity'],['H','HubSpot','CRM, marketing and customer context'],['A','Airtable','Structured bases, records and workflows'],['J','Jira','Projects, issues and engineering decisions'],['G','GitHub','Repositories, issues, pull requests and docs'],['↗','CERVEL MCP','Scoped tools for AI assistants and agents']]]];return '<section class="view"><h1>Integrations</h1><p class="sub">Connect the sources that already hold your knowledge. CERVEL ingests with provenance, permissions, and disclosure controls intact.</p><div class="notice">Demo connections are simulated and never request credentials or access visitor accounts.</div>'+groups.map(function(g){return '<div class="integration-category">'+g[0]+'</div><div class="integration-grid">'+g[1].map(function(x){return '<article class="integration-card"><div class="integration-logo">'+x[0]+'</div><h3>'+x[1]+'</h3><p>'+x[2]+'</p><button class="secondary" data-integrate="'+x[1]+'">Connect</button></article>'}).join('')+'</div>'}).join('')+'</section>'}
function searchView(){var q=state.query.toLowerCase(),found=notes.filter(function(n){return !q||n.title.toLowerCase().includes(q)||n.body.toLowerCase().includes(q)});return '<section class="view"><h1>Search the Vault</h1><p class="sub">Permission-scoped lexical + semantic retrieval</p>'+(state.filingReceipt?'<div class="filing-receipt">✓ CERVEL analyzed and filed: '+esc(state.filingReceipt)+'</div>':'')+'<div class="results">'+found.map(function(n){var m=membershipFor(n,state.corpus),filed=state.memberships&&state.memberships[state.corpus+':'+n.id];return '<div class="result-wrap"><button class="result" data-note="'+n.id+'"><b>'+esc(n.title)+'</b><p>'+esc(n.body.replace(/^# .*\n+/, '').slice(0,170))+'…</p><small>'+esc(n.source)+' · suggested '+esc(m.mega)+' › '+esc(m.sub)+'</small></button><button class="secondary archive-result" data-archive-result="'+esc(n.id)+'">'+(filed?'Filed ✓':'Archive + auto-file')+'</button></div>'}).join('')+(found.length?'':'<div class="notice">No results. Try “local-first” or “roadmap”.</div>')+'</div></section>'}
function askView(){var turns=Array.isArray(state.conversation)?state.conversation:[],suggestions=['Summarize CERVEL in three points','Why does local-first knowledge matter?','Create an investor-ready product brief'],hasAnswer=state.answer&&!state.askLoading;return '<section class="view"><div class="ask-shell"><div class="ask-hero"><div class="ask-orb">✦</div><h1>Ask CERVEL</h1><p class="sub">Fast, private-aware intelligence with a receipt for every external disclosure.</p></div>'+(!turns.length?'<div class="suggestions">'+suggestions.map(function(s){return '<button class="suggestion" data-ask-suggestion="'+esc(s)+'">'+esc(s)+'</button>'}).join('')+'</div>':'')+(turns.length?'<div class="conversation" aria-live="polite" aria-label="Ask CERVEL conversation">'+turns.map(function(t){var meta=t.role==='assistant'&&t.model?'<div class="response-meta"><span>OpenAI</span><span>'+esc(t.model)+'</span><span>Receipt '+esc(t.response_id)+'</span></div>':'';return '<div class="message '+(t.role==='user'?'user':'assistant')+'" data-conversation-turn="'+t.role+'">'+esc(t.content)+meta+'</div>'}).join('')+'</div>':'')+(state.archivedResponseId&&state.answer&&state.archivedResponseId===state.answer.response_id?'<div class="archive-receipt"><b>✓ Compiled and organized under '+esc(state.answer.archive_suggestion.vertical)+'</b> · provenance and response receipt preserved'+(state.compiledReceipt?'<div class="compilation-receipt"><span>3 claims</span><span>2 insights</span><span>1 decision</span><span>2 tasks</span></div><div class="source-strip"><button data-note="'+esc(state.compiledReceipt.id)+'">Open new CKO</button><button data-view="trace">Inspect Trace</button></div>':'')+'</div>':'')+'<div class="ask-composer"><form id="ask-form" class="ask-row"><div class="prompt-surface"><textarea id="ask-input" rows="1" maxlength="4000" autocomplete="off" placeholder="Ask CERVEL anything…" aria-label="Question" '+(state.askLoading?'disabled':'')+'></textarea></div><button type="submit" class="ask-send" data-live-ask aria-label="Send to Ask CERVEL" aria-busy="'+(state.askLoading?'true':'false')+'" '+(state.askLoading?'disabled':'')+'><span class="send-label">'+(state.askLoading?'Working…':'Ask CERVEL')+'</span><span class="send-icon">'+(state.askLoading?'···':'↑')+'</span></button></form><div class="ask-status '+(state.askError?'ask-error':'')+'" aria-live="polite">'+(state.askLoading?'<div class="thinking-row"><span class="thinking-dots"><i></i><i></i><i></i></span><span>Your question is in the conversation. CERVEL is preparing the response…</span><button class="cancel-ask" data-cancel-ask>Cancel</button></div>':esc(state.askError||'Your question is disclosed to OpenAI for this response only · provider storage disabled')+(state.askRetry?' <button class="cancel-ask" data-retry-ask>Retry</button>':''))+'</div></div>'+(hasAnswer?'<div class="conversation-actions"><button class="secondary" data-archive-answer '+(state.archivedResponseId===state.answer.response_id?'disabled':'')+'>'+(state.archivedResponseId===state.answer.response_id?'Archived in Vault':'Archive conversation in Vault')+'</button><button class="secondary" data-action="new-conversation">New conversation</button></div>':'')+'</div></section>'}
function cancelAsk(){if(activeAskController)activeAskController.abort();activeAskController=null}
async function askCervel(retryQuery){var input=document.getElementById('ask-input'),query=(retryQuery||(input&&input.value)||'').trim();if(state.askLoading)return;if(!query){state.askError='Write a question before sending.';state.askRetry='';render();requestAnimationFrame(function(){var next=document.getElementById('ask-input');if(next)next.focus()});return}var history=(state.conversation||[]).map(function(t){return{role:t.role,content:t.content}});if(retryQuery&&history.length&&history[history.length-1].role==='user'&&history[history.length-1].content===query)history.pop();var controller=new AbortController(),timer=setTimeout(function(){controller.abort()},24000);activeAskController=controller;state.askLoading=true;state.askError='';state.askRetry='';state.conversation=history.concat([{role:'user',content:query}]);event('ASK_CERVEL_QUERY_SUBMITTED','button or Enter · user turn rendered before provider request');render();try{var response=await fetch('/v1/demo/ask',{method:'POST',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify({query:query,history:history,client_id:clientId()}),signal:controller.signal}),payload=await response.json().catch(function(){return{error:'DEMO_AI_INVALID_RESPONSE'}});if(!response.ok)throw new Error(payload.message||payload.error||'ASK_CERVEL_UNAVAILABLE');if(!payload.answer)throw new Error('DEMO_AI_EMPTY_RESPONSE');state.answer=payload;state.conversation.push({role:'assistant',content:payload.answer,model:payload.model,response_id:payload.response_id});state.archivedResponseId='';event('OPENAI_ANSWER_CREATED',payload.model+' · '+payload.disclosure_receipt.latency_ms+'ms · disclosure receipt recorded')}catch(error){var code=error&&error.message;state.askRetry=query;state.askError=error.name==='AbortError'?'The request was stopped. You can retry now.':code==='DEMO_AI_NOT_CONFIGURED'?'Ask CERVEL is awaiting its OpenAI API activation.':code==='DEMO_AI_RATE_LIMITED'?'This browser reached the temporary demo allowance. Try again in a few minutes.':code==='DEMO_AI_TIMEOUT'?'OpenAI took too long to respond. Please retry—the request was safely closed.':code==='DEMO_AI_PROVIDER_UNAVAILABLE'||code==='DEMO_AI_PROVIDER_ERROR'?'OpenAI is temporarily unavailable. Please retry in a moment.':'Ask CERVEL could not complete this request. Please retry.'}finally{clearTimeout(timer);if(activeAskController===controller)activeAskController=null;state.askLoading=false;save();render()}}
function archiveConversation(){if(!state.answer||state.archivedResponseId===state.answer.response_id)return;var suggestion=state.answer.archive_suggestion||{vertical:'Inbox',title:'Ask CERVEL conversation',tags:['ask-cervel']},turns=state.conversation||[],body='# '+suggestion.title+'\n\n'+turns.map(function(t){return(t.role==='user'?'## Question\n':'## Ask CERVEL\n')+t.content}).join('\n\n')+'\n\n---\nProvider: OpenAI\nModel: '+state.answer.model+'\nResponse receipt: '+state.answer.response_id+'\nExternal disclosure: approved for this query\nProvider storage requested: false',id='conversation-'+Date.now(),n={id:id,title:suggestion.title,folder:'',tags:suggestion.tags||['ask-cervel'],body:body,source:'Ask CERVEL · OpenAI response receipt '+state.answer.response_id};notes.push(n);var filed=fileKnowledge(n,state.corpus);state.archivedResponseId=state.answer.response_id;state.compiledReceipt={id:id,claims:3,insights:2,decisions:1,tasks:2,mega:filed.mega,sub:filed.sub};event('KNOWLEDGE_COMPILED','3 claims · 2 insights · 1 decision · 2 tasks');event('CONVERSATION_ARCHIVED',filed.mega+' › '+filed.sub+' · '+suggestion.title);save();render()}
