var demoTourSteps=[['Open the user-owned Vault','Start with private Life knowledge that remains useful without surrendering ownership.','home'],['Inspect a canonical CKO','See content, semantic membership, privacy, and provenance in one readable object.','notes'],['Ask with Vault context','Ask a question; CERVEL discloses only the approved query and records a receipt.','ask'],['Compile the conversation','Archive the answer to create a classified CKO with claims, insights, decisions, and tasks.','ask'],['Verify the complete Trace','Follow the answer through claims, fragments, artifacts, sources, policy, and authority.','trace'],['Explore shared knowledge','Switch corpus lenses and navigate relationships without duplicating canonical files.','graph'],['Create a consistent deliverable','Generate an investor brief from approved canonical content with dependency tracking.','deliverables']];
