document.addEventListener('click',function(e){var c=e.target.closest&&e.target.closest('[data-investor-control]');if(!c)return;e.preventDefault();e.stopPropagation();var a=c.dataset.investorControl;if(a==='skip'){state.tour=0;event('INVESTOR_DEMO_SKIPPED','visitor exited the guided path');render();return}if(a==='back')state.tour=Math.max(1,state.tour-1);if(a==='next'){if(state.tour>=demoTourSteps.length){state.tour=0;state.tourComplete=true;state.view='home';event('INVESTOR_DEMO_COMPLETED','7-step sovereign knowledge path');render();return}state.tour++}state.view=demoTourSteps[state.tour-1][2];save();render()},true);
function onboarding(){if(state.onboarded)return'';return '<div class="onboarding"><div class="onboarding-card"><small style="color:var(--accent);font-weight:750;letter-spacing:.1em">CERVEL CORPUS EXPERIENCE</small><h1>One knowledge system.<br>Two powerful lenses.</h1><p class="sub">Choose a starting experience. You can switch at any time—your canonical knowledge never moves or duplicates.</p><div class="onboarding-grid"><button class="corpus-choice" data-onboard="life"><i>⌂</i><h2>Life Corpus</h2><p>Private, personal knowledge organized across 17 human-centered branches.</p><span class="privacy-badge">Local-first · private by default</span></button><button class="corpus-choice" data-onboard="enterprise"><i>◇</i><h2>Enterprise Corpus</h2><p>Organizational knowledge across 18 tenant-aware, authority-governed branches.</p><span class="authority-badge">Tenant scoped · role gated</span></button></div><div class="onboarding-note">This is an isolated synthetic demonstration. It never requests access to your real Vault or organization.</div></div></div>'}
