function render(){if(graphFrame)cancelAnimationFrame(graphFrame);var body=state.view==='home'?home():state.view==='notes'?notesView():state.view==='folder'?folderView():state.view==='search'?searchView():state.view==='graph'?graphView():state.view==='ask'?askView():state.view==='trace'?traceView():state.view==='integrations'?integrationsView():deliverablesView();document.getElementById('app').innerHTML='<div class="app">'+title()+rail()+explorer()+'<main class="workspace">'+scopebar()+tabs()+body+'</main>'+context()+'<footer class="status" role="contentinfo"><span>◈ Local Node</span><span>⌁ '+(state.corpus==='life'?'Life':'Enterprise')+' Corpus v1</span><span>✓ Vault verified</span><span class="end">'+notes.length+' canonical objects · zero duplication</span><span class="footer-copy">© 2026 CSIX AI LABS LLC · CERVEL Alpha · All rights reserved</span></footer></div>'+tour()+onboarding()+composer();bind();applyPreferences();if(state.view==='graph')requestAnimationFrame(initGraph);if(state.view==='ask')requestAnimationFrame(scrollAskToLatest)}
